const input = $json || {};
const required = ['status_kind','result_type','execution_context_id','thread_id','tenant_id','state_update_result','allowed_next_stage','response_generation_allowed'];
const missing = required.filter(k => !(k in input));
if (missing.length) {
  return [{ json: {
    status_kind: 'error',
    result_type: 'composition_error',
    error: {
      code: 'INVALID_RESPONSE_COMPOSITION_INPUT',
      message: 'Missing required top-level field(s) for response composition.',
      missing_fields: missing,
      details: { received_keys: Object.keys(input).sort() }
    },
    _valid: false
  }}];
}
if (input.status_kind !== 'success' || input.result_type !== 'state_update_result') {
  return [{ json: {
    status_kind: 'error',
    result_type: 'composition_error',
    error: {
      code: 'INVALID_RESPONSE_COMPOSITION_INPUT',
      message: 'Unsupported envelope for RC.',
      missing_fields: [],
      details: { status_kind: input.status_kind, result_type: input.result_type }
    },
    _valid: false
  }}];
}
if (input.allowed_next_stage !== 'WF-RC-01' || input.response_generation_allowed !== true) {
  return [{ json: {
    status_kind: 'error',
    result_type: 'composition_error',
    error: {
      code: 'COMPOSITION_NOT_ALLOWED',
      message: 'RC is not allowed to compose for this envelope.',
      missing_fields: [],
      details: { allowed_next_stage: input.allowed_next_stage, response_generation_allowed: input.response_generation_allowed }
    },
    _valid: false
  }}];
}
const sur = input.state_update_result || {};
if (!sur.status || !sur.summary) {
  return [{ json: {
    status_kind: 'error',
    result_type: 'composition_error',
    error: {
      code: 'INVALID_RESPONSE_COMPOSITION_INPUT',
      message: 'state_update_result is incomplete.',
      missing_fields: [],
      details: { state_update_result: sur }
    },
    _valid: false
  }}];
}
return [{ json: {
  ...input,
  channel: input.channel || 'telegram',
  locale: input.locale || 'ro',
  _valid: true
}}];

const env = $('RC_Validate_State_Update_Input').first().json;
const ecRow = $items('RC_Load_Execution_Context', 0, 0)?.[0]?.json || {};
const thRow = $items('RC_Load_Thread_Context', 0, 0)?.[0]?.json || {};
if (!ecRow.id) {
  return [{ json: {
    status_kind: 'error',
    result_type: 'composition_error',
    error: {
      code: 'LINEAGE_MISMATCH',
      message: 'execution_context row not found.',
      missing_fields: [],
      details: {
        execution_context_id: env.execution_context_id,
        tenant_id: env.tenant_id
      }
    },
    _context_ready: false
  }}];
}
if (ecRow.tenant_id !== env.tenant_id || ecRow.thread_id !== env.thread_id) {
  return [{ json: {
    status_kind: 'error',
    result_type: 'composition_error',
    error: {
      code: 'LINEAGE_MISMATCH',
      message: 'execution_context lineage mismatch.',
      missing_fields: [],
      details: {
        execution_context_id: env.execution_context_id,
        tenant_id: env.tenant_id,
        row_tenant_id: ecRow.tenant_id,
        thread_id: env.thread_id,
        row_thread_id: ecRow.thread_id
      }
    },
    _context_ready: false
  }}];
}
if (thRow.id && (thRow.id !== env.thread_id || thRow.tenant_id !== env.tenant_id)) {
  return [{ json: {
    status_kind: 'error',
    result_type: 'composition_error',
    error: {
      code: 'LINEAGE_MISMATCH',
      message: 'thread lineage mismatch.',
      missing_fields: [],
      details: {
        thread_id: env.thread_id,
        row_id: thRow.id,
        tenant_id: env.tenant_id,
        row_tenant_id: thRow.tenant_id
      }
    },
    _context_ready: false
  }}];
}
return [{ json: { ...env, _context_ready: true, _thread_row: thRow } }];

const env = $json;
const sur = env.state_update_result || {};
const threadRow = env._thread_row || {};
return [{ json: {
  execution_context_id: env.execution_context_id,
  thread_id: env.thread_id,
  tenant_id: env.tenant_id,
  channel: env.channel || 'telegram',
  locale: env.locale || 'ro',
  status: sur.status,
  summary: sur.summary,
  applied_write_classes: sur.applied_write_classes || [],
  blocked_write_classes: sur.blocked_write_classes || [],
  warnings: sur.warnings || [],
  followup_requests: sur.followup_requests || [],
  user_visible_facts: sur.user_visible_facts || [],
  actions_acknowledged: sur.actions_acknowledged || [],
  thread_title: threadRow.title || null,
  thread_summary: threadRow.summary || null
}}];

const labelsRo = {
  execution_state_update: 'starea execuției',
  thread_state_update: 'firul de lucru',
  memory_candidate_persistence: 'candidații de memorie',
  audit_persistence: 'auditul intern',
  domain_event_write: 'scriere de eveniment de domeniu'
};
const labelsEn = {
  execution_state_update: 'execution state',
  thread_state_update: 'thread context',
  memory_candidate_persistence: 'memory candidates',
  audit_persistence: 'audit trail',
  domain_event_write: 'domain event write'
};
const comp = $json;
const locale = comp.locale || 'ro';
const labels = locale === 'ro' ? labelsRo : labelsEn;
const labelize = (arr=[]) => arr.map(x => labels[x] || x);
const warn = (x) => {
  if (x && typeof x === 'object') {
    if (x.code && x.message) return `${x.code}: ${x.message}`;
    if (x.message) return String(x.message);
  }
  return String(x);
};
const applied = labelize(comp.applied_write_classes || []);
const blocked = labelize(comp.blocked_write_classes || []);
const warnings = (comp.warnings || []).map(warn);
const followups = (comp.followup_requests || []).map(warn);
const facts = (comp.user_visible_facts || []).map(String).filter(Boolean);
const actions = (comp.actions_acknowledged || []).map(String).filter(Boolean);
const lines = [];
if (locale === 'ro') {
  if (comp.status === 'success') lines.push('Am pregătit răspunsul final pe baza rezultatului confirmat.');
  else if (comp.status === 'partial') lines.push('Am pregătit răspunsul final, dar există și elemente rămase parțiale.');
  else if (comp.status === 'failed') lines.push('Nu am putut pregăti complet răspunsul final.');
  else lines.push('Am verificat rezultatul și nu a fost necesară nicio acțiune suplimentară.');
  lines.push(comp.summary);
  if (actions.length) lines.push(`Acțiuni confirmate: ${actions.join('; ')}.`);
  if (applied.length) lines.push(`Aplicat: ${applied.join(', ')}.`);
  if (blocked.length) lines.push(`Blocat sau rămas neaplicat: ${blocked.join(', ')}.`);
  if (facts.length) lines.push(`Context util: ${facts.join('; ')}.`);
  if (warnings.length) lines.push(`Atenționări: ${warnings.join('; ')}.`);
  if (followups.length) lines.push(`Mai am nevoie de clarificări pentru: ${followups.join('; ')}.`);
} else {
  if (comp.status === 'success') lines.push('I prepared the final response from the confirmed result.');
  else if (comp.status === 'partial') lines.push('I prepared the final response, but some elements remain partial.');
  else if (comp.status === 'failed') lines.push('I could not fully prepare the final response.');
  else lines.push('I reviewed the result and no additional action was required.');
  lines.push(comp.summary);
  if (actions.length) lines.push(`Confirmed actions: ${actions.join('; ')}.`);
  if (applied.length) lines.push(`Applied: ${applied.join(', ')}.`);
  if (blocked.length) lines.push(`Blocked or not applied: ${blocked.join(', ')}.`);
  if (facts.length) lines.push(`Useful context: ${facts.join('; ')}.`);
  if (warnings.length) lines.push(`Warnings: ${warnings.join('; ')}.`);
  if (followups.length) lines.push(`I still need clarification for: ${followups.join('; ')}.`);
}
return [{ json: {
  final_response_text: lines.filter(Boolean).join('\n'),
  response_status: comp.status,
  includes_followups: followups.length > 0,
  includes_warnings: warnings.length > 0,
  followup_count: followups.length,
  warning_count: warnings.length,
  channel: comp.channel,
  locale
}}];

const crypto = require('crypto');
const env = $('RC_Validate_State_Update_Input').first().json;
const composed = $json;
const digest = crypto.createHash('sha256')
  .update([
    env.execution_context_id,
    env.thread_id,
    env.tenant_id,
    composed.response_status,
    composed.final_response_text
  ].join('|'))
  .digest('hex')
  .slice(0, 16);
return [{ json: {
  status_kind: 'success',
  result_type: 'composed_response',
  execution_context_id: env.execution_context_id,
  thread_id: env.thread_id,
  tenant_id: env.tenant_id,
  composed_response: composed,
  output_gateway_allowed: true,
  allowed_next_stage: 'MESSAGE_OUT',
  response_generation_allowed: true,
  idempotency_key: `compose:${env.execution_context_id}:${digest}`
}}];
